// Writes dist/classic.js: the built package as one classic script that defines `ByosCommands`,
// for pages that inline their client code in a <script> and cannot load modules.
import { readFileSync, writeFileSync } from 'node:fs';

const read = name => readFileSync(new URL(`dist/${name}`, import.meta.url), 'utf8');
const IMPORT = /^import\s*\{([^}]*)\}\s*from\s*'\.\/([\w-]+\.js)';\n/gm;
const EXPORT = /^export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([\w$]+)/gm;

const order = [];
const visit = name => {
  if (order.includes(name)) return;
  for (const [, , dep] of read(name).matchAll(IMPORT)) visit(dep);
  order.push(name);
};
for (const [, name] of read('index.js').matchAll(/^export \* from '\.\/([\w-]+\.js)';$/gm)) visit(name);

const modules = order.map(name => {
  const source = read(name);
  const exported = [...source.matchAll(EXPORT)].map(match => match[1]);
  const body = source
    .replace(IMPORT, (_, names, dep) => `const {${names.replace(/\s+as\s+/g, ': ')}} = modules[${JSON.stringify(dep)}];\n`)
    .replace(/^export\s+(?=(?:async\s+)?(?:function|const|let|class)\b)/gm, '')
    .replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  if (/^\s*export\b|^\s*import\b/m.test(body)) throw new Error(`build-classic: unsupported module syntax in ${name}`);
  return `modules[${JSON.stringify(name)}] = (() => {\n${body}\nreturn { ${exported.join(', ')} };\n})();`;
});

writeFileSync(new URL('dist/classic.js', import.meta.url),
  `// Generated by build-classic.mjs from @byos/commands. Do not edit.\nvar ByosCommands = (() => {\nconst modules = {};\n${modules.join('\n')}\nreturn Object.freeze(Object.assign({}, ...Object.values(modules)));\n})();\n`);
